package com.example.strings;

public class StringToCharArray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
      String s="Manoj";
      char[] arr=s.toCharArray();
      for(char ch:arr)
      {
    	  System.out.println(ch);
      }
	}
}
